# 小小作曲家工作台
tune = 1   # 1小星星 2生日歌 3自创示例

hide()
t = "小星星：1 1 5 5 6 6 5"
d = "两次同音重复 + 跳进到5，安静而开阔"
note = "结构：起承转合的四句一段体"
if tune == 2:
    t = "生日歌：5 5 6 5 1 7"
    d = "两个同音起头，级进下行，亲切上口"
    note = "歌词押 ao 韵：好（hǎo）、你（重复乐句）"
if tune == 3:
    t = "自创示例：1 3 5 3 | 2 4 3 1"
    d = "级进与跳进交替，像走两步跳一格"
    note = "歌词押 ang 韵：阳光、脸庞、歌唱"
fill_rect(0, 130, 360, 30, "#7c3aed")
write(t, 0, 130, "#fff", 12)
fill_rect(0, 82, 360, 36, "#f1f5f9")
write(d, 0, 82, "#0f172a", 11)
pen_color("#0f172a")
pen_down()
go_to(-170, -40)
go_to(170, -40)
pen_up()
i = 0
while i < 8:
    x = -150 + i * 40
    h = 20
    if tune == 1:
        if i == 2:
            h = 44
        if i == 3:
            h = 44
        if i == 4:
            h = 64
        if i == 5:
            h = 64
        if i == 6:
            h = 44
        if i == 7:
            h = 44
    if tune == 2:
        h = 64
        if i == 2:
            h = 44
        if i == 4:
            h = 84
        if i == 5:
            h = 74
        if i == 7:
            h = 44
    if tune == 3:
        h = 30
        if i == 1:
            h = 56
        if i == 2:
            h = 84
        if i == 3:
            h = 56
        if i == 4:
            h = 40
        if i == 5:
            h = 66
        if i == 6:
            h = 50
    fill_rect(x, -40 + h / 2, 26, h, "#7c3aed")
    i = i + 1
write("柱高=音高：看旋律的台阶", 0, -80, "#64748b", 10)
write(note, 0, -115, "#b45309", 11)

